<template><div class="page-shell"><section class="page-heading"><div><p class="eyebrow">Configuration / 09</p><h2>Settings</h2><p>Configure system preferences and operational parameters.</p></div><div class="page-actions"><button class="tesla-btn" @click="reset">Reset defaults</button><button class="tesla-btn-primary" @click="saved=true">{{ saved ? 'Saved' : 'Save changes' }}</button></div></section><div class="page-grid two"><article class="data-card"><div class="card-header"><h3>General settings</h3><SettingsIcon :size="18"/></div><label class="control-row"><span class="control-label">Robot name<small>Display name in the workspace</small></span><input v-model="settings.robotName" class="text-control"/></label><label class="control-row"><span class="control-label">Operation mode<small>Current autonomy level</small></span><select v-model="settings.mode" class="select-control"><option>Autonomous</option><option>Manual</option><option>Hybrid</option><option>Maintenance</option></select></label><div class="control-row"><span class="control-label">Auto-start sequences<small>Run on system boot</small></span><button class="toggle-control" :class="{on:settings.autoStart}" @click="settings.autoStart=!settings.autoStart"><span/></button></div><div class="control-row"><span class="control-label">Safety mode<small>Collision prevention</small></span><button class="toggle-control" :class="{on:settings.safety}" @click="settings.safety=!settings.safety"><span/></button></div></article><article class="data-card"><div class="card-header"><h3>Network & performance</h3><SlidersHorizontal :size="18"/></div><label class="control-row"><span class="control-label">ROS master URI<small>Primary ROS connection</small></span><input v-model="settings.rosUri" class="text-control"/></label><label class="control-row"><span class="control-label">Robot IP<small>Local network address</small></span><input v-model="settings.robotIp" class="text-control"/></label><label class="control-row"><span class="control-label">Connection timeout<small>{{ settings.timeout }} ms</small></span><input v-model="settings.timeout" class="range-control" type="range" min="1000" max="30000" step="1000"/></label><label class="control-row"><span class="control-label">Max CPU usage<small>{{ settings.cpu }}%</small></span><input v-model="settings.cpu" class="range-control" type="range" min="50" max="100"/></label><div class="control-row"><span class="control-label">Debug mode<small>Verbose system logging</small></span><button class="toggle-control" :class="{on:settings.debug}" @click="settings.debug=!settings.debug"><span/></button></div></article></div></div></template>
<script setup lang="ts">import { ref } from 'vue'; import { Settings as SettingsIcon, SlidersHorizontal } from 'lucide-vue-next'; const saved=ref(false); const defaults=()=>({robotName:'Dino Core',mode:'Autonomous',autoStart:true,safety:true,rosUri:'http://localhost:11311',robotIp:'192.168.1.100',timeout:5000,cpu:80,debug:false}); const settings=ref(defaults()); const reset=()=>{settings.value=defaults();saved.value=false}</script>
